/* Generated by Trae Work — 平局急救方案 v12 图表 */
(function () {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var good = style.getPropertyValue('--good').trim();
  var bad = style.getPropertyValue('--bad').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();
  var bg2 = style.getPropertyValue('--bg2').trim();

  function baseGrid() {
    return { left: 50, right: 20, top: 30, bottom: 30, containLabel: true };
  }
  function baseTooltip() {
    return {
      backgroundColor: 'rgba(15,23,42,0.92)',
      borderColor: rule,
      textStyle: { color: ink, fontSize: 12 },
    };
  }
  function baseAxis() {
    return {
      axisLine: { lineStyle: { color: rule } },
      axisLabel: { color: muted, fontSize: 11 },
      splitLine: { lineStyle: { color: rule, type: 'dashed' } },
    };
  }

  // ============ 图 1: 杯赛 6 场 target_draw 修复前后 ============
  var cupLabels = ['002\n克拉约瓦', '003\n帕福斯', '004\n维京古', '006\n流浪者', '007\n安德莱', '008\n哈茨'];
  var oldTarget = [0.32, 0.33, 0.33, 0.35, 0.33, 0.31];
  var newTarget = [0.37, 0.38, 0.38, 0.40, 0.38, 0.36];
  var actualDraw = [0, 1, 0, 1, 0, 1]; // 1=平局, 0=非平局

  var chart1 = echarts.init(document.getElementById('chart-target'), null, { renderer: 'svg' });
  chart1.setOption({
    animation: false,
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: function (params) {
        var idx = params[0].dataIndex;
        var isDraw = actualDraw[idx] ? '平局' : '非平局';
        return '<b>' + cupLabels[idx].replace('\n', ' ') + '</b><br/>' +
          '修复前 target: <span style="color:' + muted + '">' + oldTarget[idx].toFixed(2) + '</span><br/>' +
          '修复后 target: <span style="color:' + accent + '">' + newTarget[idx].toFixed(2) + '</span><br/>' +
          '实际赛果: <span style="color:' + (actualDraw[idx] ? accent2 : ink) + '">' + isDraw + '</span>';
      },
    }),
    legend: {
      data: ['修复前 target_draw', '修复后 target_draw', '实际平局'],
      textStyle: { color: muted, fontSize: 11 },
      top: 0,
    },
    grid: baseGrid(),
    xAxis: Object.assign(baseAxis(), {
      type: 'category',
      data: cupLabels,
      axisLabel: { color: muted, fontSize: 10, interval: 0 },
    }),
    yAxis: Object.assign(baseAxis(), {
      type: 'value',
      min: 0.25, max: 0.45,
      axisLabel: { color: muted, fontSize: 11, formatter: function (v) { return (v * 100).toFixed(0) + '%'; } },
      splitLine: { lineStyle: { color: rule, type: 'dashed' } },
    }),
    series: [
      {
        name: '修复前 target_draw',
        type: 'bar',
        data: oldTarget,
        barWidth: 16,
        barGap: '25%',
        itemStyle: { color: muted, borderRadius: [3, 3, 0, 0] },
        label: { show: true, position: 'top', color: muted, fontSize: 10, formatter: function (p) { return (p.value * 100).toFixed(0) + '%'; } },
      },
      {
        name: '修复后 target_draw',
        type: 'bar',
        data: newTarget,
        barWidth: 16,
        itemStyle: { color: accent, borderRadius: [3, 3, 0, 0] },
        label: { show: true, position: 'top', color: accent, fontSize: 10, formatter: function (p) { return (p.value * 100).toFixed(0) + '%'; } },
      },
      {
        name: '实际平局',
        type: 'scatter',
        data: actualDraw.map(function (v, i) {
          return v ? { value: 0.425, symbol: 'triangle', symbolSize: 14, itemStyle: { color: accent2 } } : { value: null };
        }),
        label: { show: true, position: 'top', color: accent2, fontSize: 9, formatter: '平' },
      },
    ],
  });

  // ============ 图 2: 投注指南档位变化 ============
  var allLabels = ['001\n艾卜哈', '002\n克拉约瓦', '003\n帕福斯', '004\n维京古', '005\n利雅得', '006\n流浪者', '007\n安德莱', '008\n哈茨', '009\n米拉索尔'];
  // 0=single, 1=cover, 2=avoid
  var oldLevel = [1, 0, 1, 1, 0, 0, 1, 0, 0];
  var newLevel = [1, 0, 1, 1, 0, 1, 1, 1, 1];
  var levelNames = ['单选', '双选兜底', '避开'];
  var levelColors = [good, accent2, bad];

  var chart2 = echarts.init(document.getElementById('chart-guide'), null, { renderer: 'svg' });
  chart2.setOption({
    animation: false,
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: function (params) {
        var idx = params[0].dataIndex;
        var oldL = levelNames[oldLevel[idx]];
        var newL = levelNames[newLevel[idx]];
        var changed = oldLevel[idx] !== newLevel[idx] ? ' ← 变化！' : '';
        return '<b>' + allLabels[idx].replace('\n', ' ') + '</b><br/>' +
          '修复前: <span style="color:' + levelColors[oldLevel[idx]] + '">' + oldL + '</span><br/>' +
          '修复后: <span style="color:' + levelColors[newLevel[idx]] + '">' + newL + '</span>' + changed;
      },
    }),
    legend: {
      data: ['修复前档位', '修复后档位'],
      textStyle: { color: muted, fontSize: 11 },
      top: 0,
    },
    grid: baseGrid(),
    xAxis: Object.assign(baseAxis(), {
      type: 'category',
      data: allLabels,
      axisLabel: { color: muted, fontSize: 10, interval: 0 },
    }),
    yAxis: Object.assign(baseAxis(), {
      type: 'value',
      min: 0, max: 2, interval: 1,
      splitLine: { show: false },
      axisLabel: { color: muted, fontSize: 11, formatter: function (v) { return levelNames[v] || ''; } },
    }),
    series: [
      {
        name: '修复前档位',
        type: 'bar',
        data: oldLevel,
        barWidth: 16,
        barGap: '25%',
        itemStyle: {
          color: function (p) { return levelColors[p.value]; },
          borderRadius: [3, 3, 0, 0],
        },
        label: { show: true, position: 'top', color: ink, fontSize: 10, formatter: function (p) { return levelNames[p.value]; } },
      },
      {
        name: '修复后档位',
        type: 'bar',
        data: newLevel,
        barWidth: 16,
        itemStyle: {
          color: function (p) { return levelColors[p.value]; },
          borderRadius: [3, 3, 0, 0],
        },
        label: { show: true, position: 'top', color: ink, fontSize: 10, formatter: function (p) { return levelNames[p.value]; } },
      },
    ],
  });

  window.addEventListener('resize', function () {
    chart1.resize();
    chart2.resize();
  });
})();